AND (plan_no LIKE CONCAT('%', #{keyword}, '%') OR product_code LIKE CONCAT('%', #{keyword}, '%') OR product_name LIKE CONCAT('%', #{keyword}, '%'))
AND status = #{status}
AND plan_date = #{planDate}
